INSERT INTO asset_form (id, pack_id, scope, equipment_class, sort_order, title, form_spec, source_ref) VALUES
('CO-HV-GENERAL', 'CO-CREG-038', 'point', NULL, 1, 'Información general de la frontera',
 '{"fields": [{"key": "c2_4", "label": "Localización", "ref": "2.4", "type": "text", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Local, Aparmento, Oficina, etc. Donde se encuentra localizado el punto de medida"}, {"key": "c2_9", "label": "Agente RF", "ref": "2.9", "type": "text", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Agente representante de la frontera ante el Administrador del Sistema de Intercambios Comerciales. Emplear lista suministrada por el ASIC"}, {"key": "c2_10", "label": "Codigo SIC RF", "ref": "2.10", "type": "text", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Codigo SIC del Agente representante de la frontera ante el Administrador del Sistema de Intercambios Comerciales. Emplear lista suministrada por el ASIC"}, {"key": "c2_11", "label": "Exportador Físico", "ref": "2.11", "type": "text", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Exportador Físico: (Quien entrega la energia en fronteras unidireccionales, en fronteras bidireccionales quien se consideren entre las dos parte el exportador), registrado ante el Administrador del Sistema de Intercambios Comerciales."}, {"key": "c2_12", "label": "Codigo SIC EXP", "ref": "2.12", "type": "text", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Codigo SIC del Exportador Físico (Quien entrega la energia en fronteras unidireccionales, en fronteras bidireccionales quien se consideren entre las dos parte el exportador) registrado ante el Administrador del Sistema de Intercambios Comerciales."}, {"key": "c2_16", "label": "Conexión", "ref": "2.16", "type": "choice", "options": [{"code": "monofasica", "label": "Monofásica"}, {"code": "bifasica", "label": "Bifásica"}, {"code": "trifasica", "label": "Trifásica"}], "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Tipo de Conexión: Monofasica, Bifasica o Trifasica en el punto de conexión"}, {"key": "c2_17", "label": "Clase de Servicio", "ref": "2.17", "type": "choice", "options": [{"code": "residencial", "label": "Residencial"}, {"code": "comercial", "label": "Comercial"}, {"code": "industrial", "label": "Industrial"}, {"code": "provisional", "label": "Provisional"}, {"code": "oficial", "label": "Oficial"}, {"code": "alumbrado", "label": "Alumbrado"}, {"code": "otro", "label": "Otro"}], "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Clase de Servicio: Residencial, Comercial, Industrial, provisional, Oficial, Alumbrado, Otro"}, {"key": "c2_18", "label": "Estrato", "ref": "2.18", "type": "number", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Estrato socioeconomico, aplica para clientes residenciales, no residenciales es igual a 0"}, {"key": "c2_19", "label": "Factor liq. Externo", "ref": "2.19", "type": "number", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Factor multiplicador de las lecturas de energia Activa, Reactiva, o variables electricas presentadas por el Medidor."}, {"key": "c2_20", "label": "Factor liq. Interno", "ref": "2.20", "type": "number", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Factor multiplicador de las lecturas de energia Activa, Reactiva, o variables electricas presentadas por el Medidor. Puede ser parametrizado en forma interna por lo cual las lecturas presentadas por el medidor ya son afectadas por la magnitud programada"}, {"key": "c2_21", "label": "Factor de ajuste del punto de medición", "ref": "2.21", "type": "number", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Estimacion del factor de Ajuste aplicado cuando el sistema de medida no se encuentra en el punto de conexión a la red, de acuerdo al Art 19 de la resolución CREG 038 de 2014"}, {"key": "c2_22", "label": "Frontera Embebida", "ref": "2.22", "type": "boolean", "required": true, "group": "INFORMACIÓN GENERAL", "verify": "selección de la lista"}, {"key": "c2_23", "label": "Código SIC Frontera Principal", "ref": "2.23", "type": "text", "group": "INFORMACIÓN GENERAL", "verify": "Codigo SIC de la frontera principal"}, {"key": "c2_24", "label": "Tipo de Frontera", "ref": "2.24", "type": "choice", "options": [{"code": "generacion", "label": "Generación"}, {"code": "comercializacion", "label": "Comercialización"}, {"code": "para_agentes_y_usuarios", "label": "Para agentes y usuarios"}, {"code": "distribucion", "label": "Distribución"}, {"code": "enlace_internacional", "label": "Enlace internacional"}, {"code": "entre_agentes", "label": "Entre agentes"}, {"code": "interconexion_internacional", "label": "Interconexión internacional"}, {"code": "demanda_desconectable", "label": "Demanda desconectable"}, {"code": "sin_reporte_al_asic", "label": "Sin reporte al ASIC"}], "required": true, "group": "INFORMACIÓN GENERAL", "verify": "Clasificación del tipo de frontera según opciones presentadas, las cuales corresponde con las definiciones del artículo 2 de la resolución CREG 038 de 2014"}]}'::jsonb,
 'Circular CREG 119 de 2014, hoja de vida, numerales 2');

