INSERT INTO asset_form (id, pack_id, scope, equipment_class, sort_order, title, form_spec, source_ref) VALUES
('CO-HV-METER', 'CO-CREG-038', 'equipment', 'meter', 1, 'Ficha técnica del medidor',
 '{"fields": [{"key": "c3_1", "label": "Ubicación de Medidor", "ref": "3.1", "type": "choice", "options": [{"code": "poste", "label": "Poste"}, {"code": "patio", "label": "Patio"}, {"code": "interior", "label": "Interior"}, {"code": "exterior", "label": "Exterior"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Ubicación física del medidor"}, {"key": "c3_8", "label": "Proveedor o representante", "ref": "3.8", "type": "text", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Nombre comercial del proveedor o representante del equipo"}, {"key": "c3_9", "label": "Tecnología del Medidor", "ref": "3.9", "type": "choice", "options": [{"code": "estatico", "label": "Estático"}, {"code": "electromecanico", "label": "Electromecánico"}, {"code": "hibrido", "label": "Híbrido"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Clasificación del tipo de construcción del medidor según opciones"}, {"key": "c3_10", "label": "Conexión", "ref": "3.10", "type": "choice", "options": [{"code": "directa", "label": "Directa"}, {"code": "semidirecta", "label": "Semidirecta"}, {"code": "indirecta", "label": "Indirecta"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Clasificación de la medida según tipo de conexión y cantidad de elementos"}, {"key": "c3_10_1", "label": "Número de elementos de la conexión", "ref": "3.10.1", "type": "choice", "options": [{"code": "1_elemento", "label": "1 elemento"}, {"code": "2_elementos", "label": "2 elementos"}, {"code": "2_1_2_elementos", "label": "2 1/2 elementos"}, {"code": "2_elementos_aaron", "label": "2 elementos (Aarón)"}, {"code": "3_elementos", "label": "3 elementos"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Clasificación del tipo de conexión por el número de fases a medir en el sistema"}, {"key": "c3_11", "label": "Sentido de Medición", "ref": "3.11", "type": "choice", "options": [{"code": "unidireccional", "label": "Unidireccional"}, {"code": "bidireccional", "label": "Bidireccional"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Sentido de medición de la frontera"}, {"key": "c3_12", "label": "Número de Hilos", "ref": "3.12", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Número de conductores de la conexión"}, {"key": "c3_13", "label": "Número de Fases", "ref": "3.13", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Número de fases de la conexión"}, {"key": "c3_14", "label": "Tipo de Registrador", "ref": "3.14", "type": "choice", "options": [{"code": "ciclometrico", "label": "Ciclométrico"}, {"code": "display", "label": "Display"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Tipo de construcción del registrador del medidor"}, {"key": "c3_15", "label": "Cantidad Enteros", "ref": "3.15", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Cantidad de números enteros empleados en la presentación de la lectura principal de energía acumulada por el medidor"}, {"key": "c3_16", "label": "Cantidad Decimales", "ref": "3.16", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Cantidad de números decimales empleados en la presentación de la lectura principal de energía acumulada por el medidor (en ciclomentricos incluye los segmentos sobre la ultima rueda)"}, {"key": "c3_17", "label": "Tens. Nominal (V)", "ref": "3.17", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Tensión nominal de conexión del medidor (tension de fase y tension de linea expresada en voltios)"}, {"key": "c3_18", "label": "Índ. Clase (%)", "ref": "3.18", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Índice de clase del medidor según placa de características"}, {"key": "c3_19", "label": "Constante", "ref": "3.19", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Constante del medidor para contabilización de energía activa"}, {"key": "c3_20", "label": "Unidad Constante", "ref": "3.20", "type": "choice", "options": [{"code": "kwh_rev", "label": "kWh/rev"}, {"code": "rev_kwh", "label": "rev/kWh"}, {"code": "kwh_imp", "label": "kWh/imp"}, {"code": "imp_kwh", "label": "imp/kWh"}], "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Unidades en la que se expresa la constante del medidor según placa de características"}, {"key": "c3_21", "label": "Frecuencia (Hz)", "ref": "3.21", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Frecuencia nominal de medidor expresada en Hz"}, {"key": "c3_22", "label": "Ib (A)", "ref": "3.22", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Corriente básica del medidor expresada en amperios"}, {"key": "c3_23", "label": "Imax (A)", "ref": "3.23", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Corriente máxima admisible por el medidor expresada en amperios"}, {"key": "c3_24", "label": "In (A)", "ref": "3.24", "type": "number", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Corriente nominal del medidor expresada en amperios"}, {"key": "c3_25", "label": "Canal Impor. Activa", "ref": "3.25", "type": "text", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Codigo de Identificación del canal de importación de energía activa, de acuerdo a la parametrizacion y tipos de medidor"}, {"key": "c3_26", "label": "Canal Expor. Activa", "ref": "3.26", "type": "text", "required": true, "group": "MEDIDOR DE ENERGÍA ACTIVA - PRINCIPAL", "verify": "Codigo de Identificación del canal de exportación de energía activa, de acuerdo a la parametrizacion y tipos de medidor"}, {"key": "c3_31", "label": "Memoria", "ref": "3.31", "type": "choice", "options": [{"code": "no_aplica", "label": "No aplica"}, {"code": "volatil", "label": "Volátil"}, {"code": "no_volatil", "label": "No volátil"}], "required": true, "group": "Fecha retiro", "verify": "Tipo de memoria del medidor"}, {"key": "c3_32", "label": "Cap. Mem. MB", "ref": "3.32", "type": "number", "required": true, "group": "Fecha retiro", "verify": "Capacidad en MB de la memoria del medidor"}, {"key": "c3_32_1", "label": "Sistema de almacenamiento de datos", "ref": "3.32.1", "type": "choice", "options": [{"code": "no_aplica", "label": "No aplica"}, {"code": "interno", "label": "Interno"}, {"code": "externo", "label": "Externo"}], "required": true, "group": "Fecha retiro", "verify": "ubicación del sistema de almacenamiento de datos generados por el medidor"}, {"key": "c3_34", "label": "Software de Lectura Local", "ref": "3.34", "type": "text", "required": true, "group": "Fecha retiro", "verify": "Software empleado para la lectura local del equipo"}, {"key": "c3_35", "label": "Software de Lectura Remota", "ref": "3.35", "type": "text", "required": true, "group": "Fecha retiro", "verify": "Software empleado para la lectura remota del equipo"}, {"key": "c3_36", "label": "Esquemas de seguridad", "ref": "3.36", "type": "choice", "options": [{"code": "si", "label": "Sí"}, {"code": "no", "label": "No"}, {"code": "no_aplica", "label": "No aplica"}], "required": true, "group": "Fecha retiro", "verify": "Verificación del esquema de seguridad y monitoreo del sistema de medida"}, {"key": "c3_37", "label": "Puertos de Comunicación", "ref": "3.37", "type": "multi", "options": [{"code": "rs232", "label": "RS232"}, {"code": "rs485", "label": "RS485"}, {"code": "optico", "label": "Óptico"}, {"code": "ethernet", "label": "Ethernet"}, {"code": "otro", "label": "Otro"}], "required": true, "group": "Fecha retiro", "verify": "Tipo del puerto de comunicaciones"}, {"key": "c3_38_1", "label": "Número", "ref": "3.38.1", "type": "text", "required": true, "group": "Certificado de Conformidad de Producto", "verify": "Número del certificado de conformidad"}, {"key": "c3_38_2", "label": "Fecha de emisión", "ref": "3.38.2", "type": "date", "required": true, "group": "Certificado de Conformidad de Producto", "verify": "Fecha de emisión del certificado"}, {"key": "c3_38_3", "label": "Ente Emisor", "ref": "3.38.3", "type": "text", "required": true, "group": "Certificado de Conformidad de Producto", "verify": "Nombre de la entidad que emitió el certificado de conformidad"}, {"key": "c3_39", "label": "Otras declaraciones o informes", "ref": "3.39", "type": "choice", "options": [{"code": "conformidad", "label": "Conformidad"}, {"code": "declaracion_de_fabricante", "label": "Declaración de fabricante"}, {"code": "informe_de_recepcion", "label": "Informe de recepción"}, {"code": "no_aplica", "label": "No aplica"}], "required": true, "group": "Certificado de Conformidad de Producto", "verify": "Tipo de conformidad según opciones acordes con el artículo 10 de la Resolución CREG 038 de 2014"}]}'::jsonb,
 'Circular CREG 119 de 2014, hoja de vida, numerales 3');

INSERT INTO asset_form (id, pack_id, scope, equipment_class, sort_order, title, form_spec, source_ref) VALUES
