ad", "ref": "7.16.4.1", "type": "text", "group": "Otras certificaciones", "verify": "Conformidad para elemento de cada fase"}, {"key": "c7_16_4_2", "label": "Declaración de fabricante", "ref": "7.16.4.2", "type": "text", "group": "Otras certificaciones", "verify": "Declaración de fabricante para elemento de cada fase"}, {"key": "c7_16_4_3", "label": "Informe de recepción", "ref": "7.16.4.3", "type": "text", "group": "Otras certificaciones", "verify": "Informe de recepción para elemento de cada fase"}]}'::jsonb,
