, "type": "choice", "options": [{"code": "horario", "label": "Horario"}, {"code": "acumulativo", "label": "Acumulativo"}, {"code": "no_aplica", "label": "No aplica"}], "group": "COMUNICACIONES MEDIDOR PRINCIPAL", "verify": "De acuerdo a la programación de medidor; horario o acumulativo"}]}'::jsonb,
